import os, sys

files = {'data/database.py': '"""\ndata/database.py\nPostgreSQL schema + connection for the algo trader.\nTables: ticks, trades, positions, daily_pnl, signals\n"""\n\nimport os\nfrom datetime import datetime\nfrom sqlalchemy import (\n    create_engine, Column, Integer, Float, String,\n    DateTime, Boolean, Text, Index\n)\nfrom sqlalchemy.orm import declarative_base, sessionmaker\nfrom loguru import logger\n\nBase = declarative_base()\n\n\n# ── Models ────────────────────────────────────────────────────────────────────\n\nclass Tick(Base):\n    """Raw price ticks from WebSocket feed."""\n    __tablename__ = "ticks"\n    id        = Column(Integer, primary_key=True, autoincrement=True)\n    symbol    = Column(String(10), nullable=False)\n    price     = Column(Float, nullable=False)\n    volume    = Column(Float, default=0)\n    timestamp = Column(DateTime, default=datetime.utcnow, nullable=False)\n    bid       = Column(Float)\n    ask       = Column(Float)\n\n    __table_args__ = (\n        Index("ix_ticks_symbol_ts", "symbol", "timestamp"),\n    )\n\n\nclass OHLCV(Base):\n    """1-minute OHLCV bars built from ticks."""\n    __tablename__ = "ohlcv"\n    id        = Column(Integer, primary_key=True, autoincrement=True)\n    symbol    = Column(String(10), nullable=False)\n    open      = Column(Float)\n    high      = Column(Float)\n    low       = Column(Float)\n    close     = Column(Float)\n    volume    = Column(Float)\n    timestamp = Column(DateTime, nullable=False)\n    timeframe = Column(String(5), default="1min")\n\n    __table_args__ = (\n        Index("ix_ohlcv_symbol_ts", "symbol", "timestamp"),\n    )\n\n\nclass Signal(Base):\n    """Strategy signals (buy/sell/hold) with metadata."""\n    __tablename__ = "signals"\n    id         = Column(Integer, primary_key=True, autoincrement=True)\n    symbol     = Column(String(10), nullable=False)\n    strategy   = Column(String(50), nullable=False)\n    action     = Column(String(10), nullable=False)   # BUY | SELL | HOLD\n    price      = Column(Float)\n    confidence = Column(Float, default=1.0)           # 0–1\n    reason     = Column(Text)\n    timestamp  = Column(DateTime, default=datetime.utcnow)\n    acted_on   = Column(Boolean, default=False)\n\n\nclass Trade(Base):\n    """Every order placed, filled, or cancelled."""\n    __tablename__ = "trades"\n    id            = Column(Integer, primary_key=True, autoincrement=True)\n    order_id      = Column(String(50), unique=True)\n    symbol        = Column(String(10), nullable=False)\n    side          = Column(String(5), nullable=False)   # buy | sell\n    qty           = Column(Float, nullable=False)\n    filled_price  = Column(Float)\n    limit_price   = Column(Float)\n    status        = Column(String(20), default="pending")\n    strategy      = Column(String(50))\n    pnl           = Column(Float, default=0)\n    commission    = Column(Float, default=0)\n    created_at    = Column(DateTime, default=datetime.utcnow)\n    filled_at     = Column(DateTime)\n\n\nclass Position(Base):\n    """Current open positions."""\n    __tablename__ = "positions"\n    id           = Column(Integer, primary_key=True, autoincrement=True)\n    symbol       = Column(String(10), unique=True, nullable=False)\n    qty          = Column(Float, nullable=False)\n    avg_cost     = Column(Float, nullable=False)\n    current_price= Column(Float)\n    unrealized_pnl = Column(Float, default=0)\n    strategy     = Column(String(50))\n    stop_loss    = Column(Float)\n    take_profit  = Column(Float)\n    opened_at    = Column(DateTime, default=datetime.utcnow)\n    updated_at   = Column(DateTime, default=datetime.utcnow)\n\n\nclass DailyPnL(Base):\n    """Daily P&L snapshot for the dashboard charts."""\n    __tablename__ = "daily_pnl"\n    id            = Column(Integer, primary_key=True, autoincrement=True)\n    date          = Column(DateTime, nullable=False, unique=True)\n    starting_cash = Column(Float)\n    ending_cash   = Column(Float)\n    realized_pnl  = Column(Float, default=0)\n    unrealized_pnl= Column(Float, default=0)\n    total_pnl     = Column(Float, default=0)\n    total_trades  = Column(Integer, default=0)\n    win_trades    = Column(Integer, default=0)\n    portfolio_value = Column(Float)\n\n\n# ── Connection ────────────────────────────────────────────────────────────────\n\n_engine = None\n_Session = None\n\n\ndef get_engine():\n    global _engine\n    if _engine is None:\n        url = os.getenv("DATABASE_URL", "postgresql://postgres:password@localhost:5432/algotrader")\n        _engine = create_engine(url, pool_pre_ping=True, pool_size=10, max_overflow=20)\n    return _engine\n\n\ndef get_session():\n    global _Session\n    if _Session is None:\n        _Session = sessionmaker(bind=get_engine())\n    return _Session()\n\n\ndef init_db():\n    """Create all tables if they don\'t exist."""\n    engine = get_engine()\n    Base.metadata.create_all(engine)\n    logger.info("Database tables created / verified")\n\n\ndef save_tick(symbol: str, price: float, volume: float = 0, bid: float = None, ask: float = None):\n    session = get_session()\n    try:\n        tick = Tick(symbol=symbol, price=price, volume=volume, bid=bid, ask=ask)\n        session.add(tick)\n        session.commit()\n    except Exception as e:\n        session.rollback()\n        logger.error(f"save_tick error: {e}")\n    finally:\n        session.close()\n\n\ndef save_signal(symbol, strategy, action, price, reason="", confidence=1.0):\n    session = get_session()\n    try:\n        sig = Signal(symbol=symbol, strategy=strategy, action=action,\n                     price=price, reason=reason, confidence=confidence)\n        session.add(sig)\n        session.commit()\n        return sig.id\n    except Exception as e:\n        session.rollback()\n        logger.error(f"save_signal error: {e}")\n    finally:\n        session.close()\n\n\ndef save_trade(order_id, symbol, side, qty, limit_price=None, strategy=None):\n    session = get_session()\n    try:\n        trade = Trade(order_id=order_id, symbol=symbol, side=side,\n                      qty=qty, limit_price=limit_price, strategy=strategy)\n        session.add(trade)\n        session.commit()\n    except Exception as e:\n        session.rollback()\n        logger.error(f"save_trade error: {e}")\n    finally:\n        session.close()\n\n\ndef get_recent_ohlcv(symbol: str, limit: int = 100) -> list:\n    session = get_session()\n    try:\n        rows = (session.query(OHLCV)\n                .filter(OHLCV.symbol == symbol)\n                .order_by(OHLCV.timestamp.desc())\n                .limit(limit)\n                .all())\n        return list(reversed(rows))\n    finally:\n        session.close()\n\n\nclass SupplyDemandZone(Base):\n    """Persisted supply & demand zones."""\n    __tablename__ = "sd_zones"\n    id          = Column(Integer, primary_key=True, autoincrement=True)\n    symbol      = Column(String(10), nullable=False)\n    zone_type   = Column(String(1), nullable=False)   # D | S\n    s1          = Column(Float, nullable=False)        # key level\n    top         = Column(Float, nullable=False)\n    bot         = Column(Float, nullable=False)\n    active      = Column(Boolean, default=True)\n    hit_count   = Column(Integer, default=0)\n    formed_at   = Column(DateTime)\n    updated_at  = Column(DateTime, default=datetime.utcnow)\n\n    __table_args__ = (\n        Index("ix_sd_zones_symbol_type", "symbol", "zone_type"),\n    )\n\n\ndef save_sd_zone(symbol: str, zone_type: str, s1: float,\n                 top: float, bot: float, formed_at=None):\n    session = get_session()\n    try:\n        # Skip if already exists (same symbol + s1 + type)\n        existing = session.query(SupplyDemandZone).filter_by(\n            symbol=symbol, zone_type=zone_type, s1=s1\n        ).first()\n        if existing:\n            return\n        zone = SupplyDemandZone(\n            symbol=symbol, zone_type=zone_type, s1=s1,\n            top=top, bot=bot, formed_at=formed_at or datetime.utcnow()\n        )\n        session.add(zone)\n        session.commit()\n    except Exception as e:\n        session.rollback()\n        logger.error(f"save_sd_zone error: {e}")\n    finally:\n        session.close()\n\n\ndef get_active_sd_zones(symbol: str) -> list:\n    session = get_session()\n    try:\n        rows = session.query(SupplyDemandZone).filter_by(\n            symbol=symbol, active=True\n        ).order_by(SupplyDemandZone.formed_at.desc()).all()\n        return rows\n    finally:\n        session.close()\n\n\ndef deactivate_sd_zone(symbol: str, zone_type: str, s1: float):\n    session = get_session()\n    try:\n        zone = session.query(SupplyDemandZone).filter_by(\n            symbol=symbol, zone_type=zone_type, s1=s1\n        ).first()\n        if zone:\n            zone.active = False\n            zone.hit_count += 1\n            zone.updated_at = datetime.utcnow()\n            session.commit()\n    except Exception as e:\n        session.rollback()\n        logger.error(f"deactivate_sd_zone error: {e}")\n    finally:\n        session.close()\n', 'data/feed.py': '"""\ndata/feed.py\nAlpaca WebSocket live data feed.\n- Connects and auto-reconnects\n- Stores raw ticks to PostgreSQL\n- Builds 1-min OHLCV bars in memory\n- Runs heartbeat monitor (alerts if feed goes stale)\n"""\n\nimport os\nimport json\nimport time\nimport asyncio\nimport threading\nfrom datetime import datetime, timedelta\nfrom collections import defaultdict, deque\nimport websocket\nimport pandas as pd\nfrom loguru import logger\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n# ── In-memory price + bar storage ─────────────────────────────────────────────\n\nclass PriceCache:\n    """Thread-safe in-memory cache of recent prices and OHLCV bars."""\n\n    def __init__(self, max_bars: int = 200):\n        self.prices: dict[str, float] = {}          # latest price per symbol\n        self.bids: dict[str, float] = {}\n        self.asks: dict[str, float] = {}\n        self.bars: dict[str, deque] = defaultdict(lambda: deque(maxlen=max_bars))\n        self._current_bar: dict[str, dict] = {}\n        self._current_minute: dict[str, str] = {}\n        self.last_tick_time: dict[str, datetime] = {}\n        self._lock = threading.Lock()\n\n    def update_price(self, symbol: str, price: float, volume: float = 0,\n                     bid: float = None, ask: float = None):\n        with self._lock:\n            self.prices[symbol] = price\n            self.last_tick_time[symbol] = datetime.utcnow()\n            if bid: self.bids[symbol] = bid\n            if ask: self.asks[symbol] = ask\n            self._update_bar(symbol, price, volume)\n\n    def _update_bar(self, symbol: str, price: float, volume: float):\n        """Aggregate ticks into 1-minute OHLCV bars."""\n        minute = datetime.utcnow().strftime("%Y-%m-%d %H:%M")\n        if self._current_minute.get(symbol) != minute:\n            # Close the old bar and start a new one\n            if symbol in self._current_bar:\n                self.bars[symbol].append(dict(self._current_bar[symbol]))\n            self._current_bar[symbol] = {\n                "timestamp": minute,\n                "open": price, "high": price,\n                "low": price, "close": price,\n                "volume": volume\n            }\n            self._current_minute[symbol] = minute\n        else:\n            bar = self._current_bar[symbol]\n            bar["high"]   = max(bar["high"], price)\n            bar["low"]    = min(bar["low"], price)\n            bar["close"]  = price\n            bar["volume"] += volume\n\n    def get_price(self, symbol: str) -> float | None:\n        return self.prices.get(symbol)\n\n    def get_bars_df(self, symbol: str, n: int = 100) -> pd.DataFrame:\n        with self._lock:\n            bars = list(self.bars[symbol])[-n:]\n        if not bars:\n            return pd.DataFrame()\n        df = pd.DataFrame(bars)\n        df["timestamp"] = pd.to_datetime(df["timestamp"])\n        df.set_index("timestamp", inplace=True)\n        return df\n\n    def is_stale(self, symbol: str, threshold_seconds: int = 60) -> bool:\n        last = self.last_tick_time.get(symbol)\n        if not last:\n            return True\n        return (datetime.utcnow() - last).total_seconds() > threshold_seconds\n\n    def get_spread(self, symbol: str) -> float | None:\n        bid = self.bids.get(symbol)\n        ask = self.asks.get(symbol)\n        if bid and ask:\n            return ask - bid\n        return None\n\n\n# Global cache — shared across the app\nprice_cache = PriceCache()\n\n\n# ── WebSocket Feed ─────────────────────────────────────────────────────────────\n\nclass AlpacaFeed:\n    """\n    Alpaca WebSocket data feed.\n    Subscribes to trades + quotes for configured symbols.\n    Auto-reconnects on disconnect.\n    """\n\n    WS_URL = "wss://stream.data.alpaca.markets/v2/iex"  # free IEX feed\n    # WS_URL = "wss://stream.data.alpaca.markets/v2/sip"  # paid SIP feed\n\n    def __init__(self, symbols: list[str], on_signal_callback=None):\n        self.symbols = [s.upper() for s in symbols]\n        self.on_signal_callback = on_signal_callback\n        self.api_key = os.getenv("ALPACA_API_KEY")\n        self.secret_key = os.getenv("ALPACA_SECRET_KEY")\n        self.ws = None\n        self.connected = False\n        self.reconnect_delay = 5\n        self._stop = False\n        self._tick_callbacks: list = []\n\n    def add_tick_callback(self, fn):\n        """Register a function to call on every price update."""\n        self._tick_callbacks.append(fn)\n\n    def _on_open(self, ws):\n        logger.info("WebSocket connected — authenticating...")\n        auth = {"action": "auth", "key": self.api_key, "secret": self.secret_key}\n        ws.send(json.dumps(auth))\n\n    def _on_message(self, ws, message):\n        try:\n            data = json.loads(message)\n            if isinstance(data, list):\n                for msg in data:\n                    self._handle_message(msg)\n            else:\n                self._handle_message(data)\n        except Exception as e:\n            logger.error(f"WebSocket message error: {e}")\n\n    def _handle_message(self, msg):\n        t = msg.get("T")\n\n        if t == "success" and msg.get("msg") == "authenticated":\n            logger.success("Authenticated — subscribing to symbols...")\n            sub = {\n                "action": "subscribe",\n                "trades": self.symbols,\n                "quotes": self.symbols,\n            }\n            self.ws.send(json.dumps(sub))\n            self.connected = True\n\n        elif t == "t":   # trade tick\n            symbol = msg.get("S")\n            price  = float(msg.get("p", 0))\n            volume = float(msg.get("s", 0))\n\n            if price > 0:\n                price_cache.update_price(symbol, price, volume)\n                for cb in self._tick_callbacks:\n                    try:\n                        cb(symbol, price, volume)\n                    except Exception as e:\n                        logger.error(f"Tick callback error: {e}")\n\n        elif t == "q":   # quote update\n            symbol = msg.get("S")\n            bid    = float(msg.get("bp", 0) or 0)\n            ask    = float(msg.get("ap", 0) or 0)\n            if bid and ask:\n                price_cache.update_price(symbol, (bid + ask) / 2, bid=bid, ask=ask)\n\n        elif t == "error":\n            logger.error(f"Feed error: {msg}")\n\n    def _on_error(self, ws, error):\n        logger.error(f"WebSocket error: {error}")\n        self.connected = False\n\n    def _on_close(self, ws, close_status, close_msg):\n        logger.warning(f"WebSocket closed: {close_status} {close_msg}")\n        self.connected = False\n\n    def _heartbeat_monitor(self):\n        """Alert if any symbol\'s feed goes stale."""\n        while not self._stop:\n            time.sleep(30)\n            for symbol in self.symbols:\n                if price_cache.is_stale(symbol, threshold_seconds=120):\n                    logger.warning(f"⚠️  Feed may be stale for {symbol} — no tick in 2+ minutes")\n\n    def start(self):\n        """Start the feed in a background thread with auto-reconnect."""\n        threading.Thread(target=self._heartbeat_monitor, daemon=True).start()\n\n        while not self._stop:\n            try:\n                logger.info(f"Connecting to Alpaca feed for: {self.symbols}")\n                self.ws = websocket.WebSocketApp(\n                    self.WS_URL,\n                    on_open=self._on_open,\n                    on_message=self._on_message,\n                    on_error=self._on_error,\n                    on_close=self._on_close,\n                )\n                self.ws.run_forever(ping_interval=30, ping_timeout=10)\n            except Exception as e:\n                logger.error(f"Feed crashed: {e}")\n\n            if not self._stop:\n                logger.info(f"Reconnecting in {self.reconnect_delay}s...")\n                time.sleep(self.reconnect_delay)\n                self.reconnect_delay = min(self.reconnect_delay * 2, 60)\n\n    def stop(self):\n        self._stop = True\n        if self.ws:\n            self.ws.close()\n\n\ndef start_feed(symbols: list[str], tick_callbacks: list = None) -> AlpacaFeed:\n    """Start the live feed in a daemon thread. Returns the feed instance."""\n    feed = AlpacaFeed(symbols)\n    if tick_callbacks:\n        for cb in tick_callbacks:\n            feed.add_tick_callback(cb)\n    thread = threading.Thread(target=feed.start, daemon=True, name="AlpacaFeed")\n    thread.start()\n    return feed\n', 'strategies/momentum.py': '"""\nstrategies/momentum.py\nMomentum Strategy: MA Crossover + RSI Filter\n\nSignal logic:\n  BUY  when: fast MA crosses above slow MA AND RSI < 65 (not overbought)\n  SELL when: fast MA crosses below slow MA OR  RSI > 75 (overbought)\n\nWorks best on: trending markets, liquid ETFs (SPY, QQQ)\nTimeframe: 1-minute bars, swing timeframe\n"""\n\nimport pandas as pd\nimport numpy as np\nfrom loguru import logger\n\n\nclass MomentumStrategy:\n\n    NAME = "momentum_ma_rsi"\n\n    def __init__(self,\n                 fast_ma: int = 10,\n                 slow_ma: int = 30,\n                 rsi_period: int = 14,\n                 rsi_overbought: float = 75,\n                 rsi_oversold: float = 35):\n        self.fast_ma = fast_ma\n        self.slow_ma = slow_ma\n        self.rsi_period = rsi_period\n        self.rsi_overbought = rsi_overbought\n        self.rsi_oversold = rsi_oversold\n        self._prev_fast: dict[str, float] = {}\n        self._prev_slow: dict[str, float] = {}\n\n    # ── Indicators ─────────────────────────────────────────────────────────────\n\n    def _calc_rsi(self, closes: pd.Series, period: int) -> pd.Series:\n        delta = closes.diff()\n        gain  = delta.clip(lower=0).rolling(period).mean()\n        loss  = (-delta.clip(upper=0)).rolling(period).mean()\n        rs    = gain / (loss + 1e-10)\n        return 100 - (100 / (1 + rs))\n\n    def _calc_indicators(self, df: pd.DataFrame) -> pd.DataFrame:\n        df = df.copy()\n        df["fast_ma"] = df["close"].rolling(self.fast_ma).mean()\n        df["slow_ma"] = df["close"].rolling(self.slow_ma).mean()\n        df["rsi"]     = self._calc_rsi(df["close"], self.rsi_period)\n        df["volume_ma"] = df["volume"].rolling(20).mean()\n        df["volume_surge"] = df["volume"] > df["volume_ma"] * 1.5\n        return df\n\n    # ── Signal generation ──────────────────────────────────────────────────────\n\n    def generate_signal(self, symbol: str, df: pd.DataFrame) -> dict | None:\n        """\n        Returns a signal dict or None if no trade.\n        Signal: { action, price, reason, confidence }\n        """\n        if len(df) < self.slow_ma + self.rsi_period:\n            return None   # not enough data yet\n\n        df = self._calc_indicators(df)\n        df.dropna(inplace=True)\n        if df.empty:\n            return None\n\n        latest   = df.iloc[-1]\n        prev     = df.iloc[-2]\n\n        fast_now  = latest["fast_ma"]\n        slow_now  = latest["slow_ma"]\n        fast_prev = prev["fast_ma"]\n        slow_prev = prev["slow_ma"]\n        rsi       = latest["rsi"]\n        price     = latest["close"]\n        vol_surge = latest["volume_surge"]\n\n        # ── BUY signal: golden cross ──────────────────────────────────────────\n        if (fast_prev <= slow_prev and        # was below\n            fast_now  >  slow_now  and        # crossed above\n            rsi < self.rsi_overbought):       # not overbought\n\n            confidence = 0.7\n            if vol_surge: confidence += 0.15  # volume confirms\n            if rsi < 50:  confidence += 0.10  # room to run\n            confidence = min(confidence, 1.0)\n\n            reason = (f"MA crossover UP: fast={fast_now:.2f} > slow={slow_now:.2f}, "\n                      f"RSI={rsi:.1f}" + (" | volume surge" if vol_surge else ""))\n            logger.info(f"[MOMENTUM] BUY signal {symbol} @ {price:.2f} — {reason}")\n            return {"action": "BUY", "price": price,\n                    "reason": reason, "confidence": confidence}\n\n        # ── SELL signal: death cross ──────────────────────────────────────────\n        if (fast_prev >= slow_prev and        # was above\n            fast_now  <  slow_now):           # crossed below\n\n            reason = (f"MA crossover DOWN: fast={fast_now:.2f} < slow={slow_now:.2f}, "\n                      f"RSI={rsi:.1f}")\n            logger.info(f"[MOMENTUM] SELL signal {symbol} @ {price:.2f} — {reason}")\n            return {"action": "SELL", "price": price, "reason": reason, "confidence": 0.8}\n\n        # ── SELL signal: RSI overbought ───────────────────────────────────────\n        if rsi > self.rsi_overbought:\n            reason = f"RSI overbought: {rsi:.1f} > {self.rsi_overbought}"\n            return {"action": "SELL", "price": price, "reason": reason, "confidence": 0.6}\n\n        return None   # hold\n\n    def get_stats(self, df: pd.DataFrame) -> dict:\n        """Return current indicator values for the dashboard."""\n        if len(df) < self.slow_ma:\n            return {}\n        df = self._calc_indicators(df)\n        df.dropna(inplace=True)\n        if df.empty:\n            return {}\n        latest = df.iloc[-1]\n        return {\n            "fast_ma": round(latest["fast_ma"], 2),\n            "slow_ma": round(latest["slow_ma"], 2),\n            "rsi": round(latest["rsi"], 1),\n            "volume_surge": bool(latest["volume_surge"]),\n        }\n', 'strategies/mean_reversion.py': '"""\nstrategies/mean_reversion.py\nMean Reversion Strategy: Bollinger Bands + RSI\n\nSignal logic:\n  BUY  when: price touches/breaks lower Bollinger Band AND RSI < 30 (oversold)\n  SELL when: price touches/breaks upper Bollinger Band OR  RSI > 70 (overbought)\n\nWorks best on: range-bound markets, stable large-cap stocks\nTimeframe: 1-minute bars\n"""\n\nimport pandas as pd\nimport numpy as np\nfrom loguru import logger\n\n\nclass MeanReversionStrategy:\n\n    NAME = "mean_reversion_bb_rsi"\n\n    def __init__(self,\n                 bb_period: int = 20,\n                 bb_std: float = 2.0,\n                 rsi_period: int = 14,\n                 rsi_oversold: float = 30,\n                 rsi_overbought: float = 70):\n        self.bb_period = bb_period\n        self.bb_std = bb_std\n        self.rsi_period = rsi_period\n        self.rsi_oversold = rsi_oversold\n        self.rsi_overbought = rsi_overbought\n\n    # ── Indicators ─────────────────────────────────────────────────────────────\n\n    def _calc_bollinger(self, closes: pd.Series) -> tuple:\n        mid   = closes.rolling(self.bb_period).mean()\n        std   = closes.rolling(self.bb_period).std()\n        upper = mid + self.bb_std * std\n        lower = mid - self.bb_std * std\n        return upper, mid, lower\n\n    def _calc_rsi(self, closes: pd.Series) -> pd.Series:\n        delta = closes.diff()\n        gain  = delta.clip(lower=0).rolling(self.rsi_period).mean()\n        loss  = (-delta.clip(upper=0)).rolling(self.rsi_period).mean()\n        rs    = gain / (loss + 1e-10)\n        return 100 - (100 / (1 + rs))\n\n    def _calc_indicators(self, df: pd.DataFrame) -> pd.DataFrame:\n        df = df.copy()\n        df["rsi"] = self._calc_rsi(df["close"])\n        df["bb_upper"], df["bb_mid"], df["bb_lower"] = self._calc_bollinger(df["close"])\n        df["bb_pct"] = (df["close"] - df["bb_lower"]) / (df["bb_upper"] - df["bb_lower"] + 1e-10)\n        # Price momentum (3-bar)\n        df["momentum"] = df["close"].pct_change(3)\n        return df\n\n    # ── Signal generation ──────────────────────────────────────────────────────\n\n    def generate_signal(self, symbol: str, df: pd.DataFrame) -> dict | None:\n        min_bars = max(self.bb_period, self.rsi_period) + 5\n        if len(df) < min_bars:\n            return None\n\n        df = self._calc_indicators(df)\n        df.dropna(inplace=True)\n        if df.empty:\n            return None\n\n        latest = df.iloc[-1]\n        price  = latest["close"]\n        rsi    = latest["rsi"]\n        bb_pct = latest["bb_pct"]         # 0=lower band, 1=upper band\n\n        # ── BUY: oversold bounce ──────────────────────────────────────────────\n        if (price <= latest["bb_lower"] * 1.002 and   # at or below lower band\n            rsi < self.rsi_oversold):                  # RSI confirms oversold\n\n            confidence = 0.65\n            if bb_pct < -0.05: confidence += 0.15     # well below band\n            if rsi < 25:       confidence += 0.10     # deeply oversold\n            confidence = min(confidence, 1.0)\n\n            reason = (f"Oversold bounce: price={price:.2f} at lower BB={latest[\'bb_lower\']:.2f}, "\n                      f"RSI={rsi:.1f}")\n            logger.info(f"[MEAN REV] BUY signal {symbol} @ {price:.2f} — {reason}")\n            return {"action": "BUY", "price": price,\n                    "reason": reason, "confidence": confidence}\n\n        # ── SELL: overbought reversal ─────────────────────────────────────────\n        if (price >= latest["bb_upper"] * 0.998 and   # at or above upper band\n            rsi > self.rsi_overbought):                # RSI confirms overbought\n\n            reason = (f"Overbought reversal: price={price:.2f} at upper BB={latest[\'bb_upper\']:.2f}, "\n                      f"RSI={rsi:.1f}")\n            logger.info(f"[MEAN REV] SELL signal {symbol} @ {price:.2f} — {reason}")\n            return {"action": "SELL", "price": price, "reason": reason, "confidence": 0.75}\n\n        return None\n\n    def get_stats(self, df: pd.DataFrame) -> dict:\n        """Return current indicator values for the dashboard."""\n        if len(df) < self.bb_period:\n            return {}\n        df = self._calc_indicators(df)\n        df.dropna(inplace=True)\n        if df.empty:\n            return {}\n        latest = df.iloc[-1]\n        return {\n            "rsi": round(latest["rsi"], 1),\n            "bb_upper": round(latest["bb_upper"], 2),\n            "bb_mid": round(latest["bb_mid"], 2),\n            "bb_lower": round(latest["bb_lower"], 2),\n            "bb_pct": round(latest["bb_pct"], 3),\n        }\n', 'strategies/supply_demand.py': '"""\nstrategies/supply_demand.py\nSupply & Demand Zone Strategy\nConverted from Pine Script: Supply & Demand Zones [BacktestBot] v1.1\n\nWhat this does:\n  - Detects demand zones (price likely to bounce UP from)\n  - Detects supply zones  (price likely to reverse DOWN from)\n  - Tracks active vs hit zones\n  - Generates BUY signal when price hits/approaches a demand zone\n  - Generates SELL signal when price hits/approaches a supply zone\n  - Stores all zones to PostgreSQL for persistence + dashboard display\n\nPine Script → Python mapping:\n  bear_run / bull_run     → count consecutive bearish/bullish candles\n  s1_level                → base price of the zone (open of first candle in run)\n  add_ds_zone()           → SupplyDemandStrategy.detect_zones()\n  check_ds_zone_hit()     → SupplyDemandStrategy.check_zone_hits()\n  draw_nearby_ds_s1()     → SupplyDemandStrategy.get_nearby_zones()\n"""\n\nimport pandas as pd\nimport numpy as np\nfrom dataclasses import dataclass, field\nfrom datetime import datetime\nfrom loguru import logger\nfrom typing import Literal\n\n\n# ── Zone data structures ──────────────────────────────────────────────────────\n\n@dataclass\nclass Zone:\n    zone_type: Literal["D", "S"]    # D=Demand, S=Supply\n    s1: float                        # key price level (top of demand / bottom of supply)\n    top: float                       # upper boundary\n    bot: float                       # lower boundary\n    formed_at: datetime              # when the zone was created\n    formed_index: int                # bar index when zone was created\n    active: bool = True              # False once price hits it\n    hit_count: int = 0               # how many times price touched it\n\n    @property\n    def midpoint(self) -> float:\n        return (self.top + self.bot) / 2\n\n    @property\n    def height_pct(self) -> float:\n        return abs(self.top - self.bot) / self.bot * 100\n\n    def to_dict(self) -> dict:\n        return {\n            "zone_type": self.zone_type,\n            "s1": round(self.s1, 4),\n            "top": round(self.top, 4),\n            "bot": round(self.bot, 4),\n            "formed_at": self.formed_at.isoformat(),\n            "active": self.active,\n            "hit_count": self.hit_count,\n            "height_pct": round(self.height_pct, 3),\n        }\n\n\n# ── Core strategy ─────────────────────────────────────────────────────────────\n\nclass SupplyDemandStrategy:\n\n    NAME = "supply_demand_zones"\n\n    def __init__(\n        self,\n        min_pc_change: float = 0.25,      # Pine: ds_min_pc_change\n        max_pc_zone: float = 0.6,          # Pine: ds_max_pc_zone\n        line_pc_display: float = 3.0,      # Pine: ds_line_pc_display\n        alerts_pc_near: float = 1.5,       # Pine: ds_alerts_pc_near\n        max_zones: int = 100,              # Pine: ds_max_zones\n    ):\n        self.min_pc_change = min_pc_change\n        self.max_pc_zone = max_pc_zone\n        self.line_pc_display = line_pc_display\n        self.alerts_pc_near = alerts_pc_near\n        self.max_zones = max_zones\n\n        # Active zone stores (mirrors Pine Script arrays)\n        self.demand_zones: list[Zone] = []\n        self.supply_zones: list[Zone] = []\n\n        # Track which zone timestamps we\'ve already added (dedup)\n        self._demand_times_seen: set = set()\n        self._supply_times_seen: set = set()\n\n    # ── Utility functions (converted from Pine Script) ────────────────────────\n\n    def _pc_diff_abs(self, x_start: float, y_end: float) -> float:\n        """Pine: get_pc_diff_abs — absolute % difference between two prices."""\n        if x_start == 0:\n            return 0\n        return abs((y_end - x_start) / x_start * 100)\n\n    def _amount_by_pc(self, amount: float, pc: float, direction: str) -> float:\n        """Pine: get_amount_by_pc — adjust a price by a percentage."""\n        pc_amount = amount * (pc / 100)\n        return amount + pc_amount if direction == "add" else amount - pc_amount\n\n    def _count_run(self, df: pd.DataFrame, direction: str) -> pd.Series:\n        """\n        Pine: bear_run / bull_run\n        Count consecutive bearish (direction=\'bear\') or bullish (\'bull\') candles.\n        Returns a Series where each value = bars since the run started.\n        """\n        if direction == "bull":\n            is_candle = df["open"] > df["close"]   # bullish = close > open\n        else:\n            is_candle = df["open"] < df["close"]   # bearish = close < open\n\n        # Count how many bars since last opposite candle\n        run = pd.Series(0, index=df.index)\n        count = 0\n        for i in range(len(df)):\n            if is_candle.iloc[i]:\n                count = 0\n            else:\n                count += 1\n            run.iloc[i] = count\n        return run\n\n    # ── Zone detection (converted from add_ds_zone) ───────────────────────────\n\n    def detect_zones(self, df: pd.DataFrame, symbol: str) -> tuple[list[Zone], list[Zone]]:\n        """\n        Main zone detection — equivalent to add_ds_zone() in Pine Script.\n        Scans all bars in df and returns (demand_zones, supply_zones).\n        Call this on startup with historical data, then incrementally.\n        """\n        if len(df) < 5:\n            return self.demand_zones, self.supply_zones\n\n        opens  = df["open"].values\n        closes = df["close"].values\n        highs  = df["high"].values\n        lows   = df["low"].values\n        times  = df.index.tolist()\n\n        # ── Pine: bull_run / bear_run ─────────────────────────────────────────\n        # bull_run[i] = bars since open < close (bearish candle interrupted bull run)\n        # In Python we iterate forward; Pine looks back\n        for i in range(2, len(df)):\n            o, c = opens[i], closes[i]\n            o1, c1 = opens[i-1], closes[i-1]\n            o2, c2 = opens[i-2], closes[i-2]\n            ts = times[i-1]         # s1_time = time[1] in Pine (one bar behind)\n\n            # ── Bull run detection → Demand zone ────────────────────────────\n            # Pine: bull_run == 1 means this bar completed a bullish run\n            # A bull run ends when a bearish candle appears after ≥1 bullish\n            bull_run = self._get_run_length(opens, closes, i, "bull")\n            bear_run = self._get_run_length(opens, closes, i, "bear")\n\n            # ── s1_level logic (Pine lines 90-100) ──────────────────────────\n            # Doji case: prev candle is nearly flat and one before is opposite\n            is_doji = self._pc_diff_abs(o1, c1) < 0.02\n\n            s1_level_demand = None\n            s1_level_supply = None\n\n            if bull_run >= 1:\n                # Demand zone: price ran up, s1 is where it started\n                s1_idx = i - bull_run          # bar where bull run began\n                s1_level_demand = opens[s1_idx] if not is_doji else opens[i-2]\n                bars_to_s1 = bull_run\n\n                pc_change = self._pc_diff_abs(closes[i], opens[i - bars_to_s1 + 1]) if bars_to_s1 >= 1 else 0\n                ts_key = str(ts)\n\n                if pc_change >= self.min_pc_change and ts_key not in self._demand_times_seen:\n                    zone = self._build_zone("D", df, i, bull_run, s1_level_demand, ts)\n                    if zone:\n                        self.demand_zones.insert(0, zone)\n                        self._demand_times_seen.add(ts_key)\n                        self._trim_zones("D")\n                        logger.debug(f"[S&D] Demand zone added for {symbol}: "\n                                     f"${zone.bot:.2f}–${zone.top:.2f}")\n\n            if bear_run >= 1:\n                # Supply zone: price ran down, s1 is where it started\n                s1_idx = i - bear_run\n                s1_level_supply = opens[s1_idx] if not is_doji else opens[i-2]\n                bars_to_s1 = bear_run\n\n                pc_change = self._pc_diff_abs(closes[i], opens[i - bars_to_s1 + 1]) if bars_to_s1 >= 1 else 0\n                ts_key = str(ts)\n\n                if pc_change >= self.min_pc_change and ts_key not in self._supply_times_seen:\n                    zone = self._build_zone("S", df, i, bear_run, s1_level_supply, ts)\n                    if zone:\n                        self.supply_zones.insert(0, zone)\n                        self._supply_times_seen.add(ts_key)\n                        self._trim_zones("S")\n                        logger.debug(f"[S&D] Supply zone added for {symbol}: "\n                                     f"${zone.bot:.2f}–${zone.top:.2f}")\n\n        return self.demand_zones, self.supply_zones\n\n    def _get_run_length(self, opens, closes, current_idx, direction) -> int:\n        """Count how many consecutive bull/bear candles ending at current_idx - 1."""\n        count = 0\n        for j in range(current_idx - 1, -1, -1):\n            if direction == "bull" and closes[j] > opens[j]:\n                count += 1\n            elif direction == "bear" and closes[j] < opens[j]:\n                count += 1\n            else:\n                break\n        return count\n\n    def _build_zone(self, zone_type: str, df: pd.DataFrame,\n                    i: int, bars_to_s1: int, s1_level: float, ts) -> Zone | None:\n        """\n        Build a Zone object from bar data.\n        Equivalent to the top/bot calculation in add_ds_zone() Pine Script.\n        """\n        opens  = df["open"].values\n        closes = df["close"].values\n        highs  = df["high"].values\n        lows   = df["low"].values\n\n        if bars_to_s1 < 1 or i - bars_to_s1 < 0:\n            return None\n\n        s1_idx = max(i - bars_to_s1, 0)\n\n        if zone_type == "S":\n            # Supply: top is the high of the run start, bot is s1_level\n            top = max(highs[s1_idx], highs[min(s1_idx + 1, len(highs)-1)])\n            bot = s1_level\n        else:\n            # Demand: top is s1_level, bot is the low of the run start\n            top = s1_level\n            bot = min(lows[s1_idx], lows[min(s1_idx + 1, len(lows)-1)])\n\n        # ── Pine: adjust zone if it\'s too big ────────────────────────────────\n        top_bot_pc_diff = self._pc_diff_abs(top, bot)\n        candle_before_pc = self._pc_diff_abs(opens[s1_idx], closes[s1_idx])\n\n        if zone_type == "S" and top_bot_pc_diff > self.max_pc_zone:\n            if candle_before_pc <= self.max_pc_zone:\n                bot = s1_level\n            else:\n                bot = self._amount_by_pc(closes[s1_idx], self.max_pc_zone / 5, "minus")\n            top = self._amount_by_pc(bot, self.max_pc_zone, "add")\n\n        elif zone_type == "D" and top_bot_pc_diff > self.max_pc_zone:\n            if candle_before_pc <= self.max_pc_zone:\n                top = s1_level\n            else:\n                top = self._amount_by_pc(closes[s1_idx], self.max_pc_zone / 5, "add")\n            bot = self._amount_by_pc(top, self.max_pc_zone, "minus")\n\n        top = round(top, 6)\n        bot = round(bot, 6)\n        s1  = bot if zone_type == "S" else top   # Pine: _s1 = _bot for S, _top for D\n\n        formed_at = ts if isinstance(ts, datetime) else datetime.utcnow()\n\n        return Zone(\n            zone_type=zone_type,\n            s1=s1,\n            top=top,\n            bot=bot,\n            formed_at=formed_at,\n            formed_index=i,\n        )\n\n    def _trim_zones(self, zone_type: str):\n        """\n        Pine: trim inactive zones when over max_zones.\n        Remove oldest inactive zones first.\n        """\n        zones = self.demand_zones if zone_type == "D" else self.supply_zones\n        if len(zones) > self.max_zones:\n            # Remove inactive from the end first\n            inactive = [z for z in zones if not z.active]\n            for z in reversed(inactive):\n                zones.remove(z)\n                if len(zones) <= self.max_zones:\n                    break\n\n    # ── Zone hit detection (converted from check_ds_zone_hit) ─────────────────\n\n    def check_zone_hits(self, current_high: float, current_low: float,\n                        current_price: float) -> list[dict]:\n        """\n        Pine: check_ds_zone_hit()\n        Check if price has hit or is near any active zone.\n        Returns list of signal dicts for the trading engine.\n        """\n        signals = []\n\n        # ── Demand zones (buy signal) ─────────────────────────────────────────\n        for zone in list(self.demand_zones):\n            if not zone.active:\n                continue\n\n            price_near = self._amount_by_pc(zone.s1, self.alerts_pc_near, "add")\n\n            if current_low <= zone.s1:\n                # HIT — price entered the demand zone\n                zone.active = False\n                zone.hit_count += 1\n                signals.append({\n                    "action": "BUY",\n                    "zone_type": "D",\n                    "alert_type": "H",   # Hit\n                    "s1": zone.s1,\n                    "top": zone.top,\n                    "bot": zone.bot,\n                    "price": current_price,\n                    "reason": f"Demand zone HIT @ ${zone.s1:.4f} (zone ${zone.bot:.4f}–${zone.top:.4f})",\n                    "confidence": 0.75,\n                })\n                logger.info(f"[S&D] 🟢 DEMAND ZONE HIT @ ${zone.s1:.4f}")\n\n            elif current_low <= price_near:\n                # NEAR — price approaching demand zone\n                signals.append({\n                    "action": "BUY",\n                    "zone_type": "D",\n                    "alert_type": "N",   # Near\n                    "s1": zone.s1,\n                    "top": zone.top,\n                    "bot": zone.bot,\n                    "price": current_price,\n                    "reason": f"Approaching demand zone @ ${zone.s1:.4f} (within {self.alerts_pc_near}%)",\n                    "confidence": 0.55,\n                })\n                logger.debug(f"[S&D] Demand zone approaching @ ${zone.s1:.4f}")\n\n            # Pine: loop_break_pc = 5 — stop checking if price is too far away\n            elif current_low > zone.s1 and self._pc_diff_abs(current_low, zone.s1) > 5:\n                break\n\n        # ── Supply zones (sell signal) ────────────────────────────────────────\n        for zone in list(self.supply_zones):\n            if not zone.active:\n                continue\n\n            price_near = self._amount_by_pc(zone.s1, self.alerts_pc_near, "minus")\n\n            if current_high >= zone.s1:\n                # HIT — price entered supply zone\n                zone.active = False\n                zone.hit_count += 1\n                signals.append({\n                    "action": "SELL",\n                    "zone_type": "S",\n                    "alert_type": "H",\n                    "s1": zone.s1,\n                    "top": zone.top,\n                    "bot": zone.bot,\n                    "price": current_price,\n                    "reason": f"Supply zone HIT @ ${zone.s1:.4f} (zone ${zone.bot:.4f}–${zone.top:.4f})",\n                    "confidence": 0.75,\n                })\n                logger.info(f"[S&D] 🔴 SUPPLY ZONE HIT @ ${zone.s1:.4f}")\n\n            elif current_high >= price_near:\n                signals.append({\n                    "action": "SELL",\n                    "zone_type": "S",\n                    "alert_type": "N",\n                    "s1": zone.s1,\n                    "top": zone.top,\n                    "bot": zone.bot,\n                    "price": current_price,\n                    "reason": f"Approaching supply zone @ ${zone.s1:.4f} (within {self.alerts_pc_near}%)",\n                    "confidence": 0.55,\n                })\n                logger.debug(f"[S&D] Supply zone approaching @ ${zone.s1:.4f}")\n\n            elif current_high < zone.s1 and self._pc_diff_abs(current_high, zone.s1) > 5:\n                break\n\n        return signals\n\n    # ── generate_signal — same interface as momentum.py / mean_reversion.py ───\n\n    def generate_signal(self, symbol: str, df: pd.DataFrame) -> dict | None:\n        """\n        Called by main.py trading loop every 60 seconds.\n        Detects new zones from latest bars and checks for hits.\n        Returns first actionable signal or None.\n        """\n        if len(df) < 10:\n            return None\n\n        # Run zone detection on latest bars (incremental — only last 50 bars)\n        recent = df.tail(50).copy()\n        self.detect_zones(recent, symbol)\n\n        # Check current bar for zone hits\n        latest = df.iloc[-1]\n        current_high  = latest["high"]\n        current_low   = latest["low"]\n        current_price = latest["close"]\n\n        signals = self.check_zone_hits(current_high, current_low, current_price)\n\n        if not signals:\n            return None\n\n        # Prioritise HIT over NEAR, then highest confidence\n        signals.sort(key=lambda s: (s["alert_type"] == "H", s["confidence"]), reverse=True)\n        best = signals[0]\n\n        return {\n            "action": best["action"],\n            "price": best["price"],\n            "reason": best["reason"],\n            "confidence": best["confidence"],\n            "zone_top": best["top"],\n            "zone_bot": best["bot"],\n        }\n\n    # ── Nearby zones (for dashboard display) ─────────────────────────────────\n\n    def get_nearby_zones(self, current_price: float) -> dict:\n        """\n        Pine: draw_nearby_ds_s1()\n        Returns active zones within line_pc_display% of current price.\n        Used by the dashboard to show relevant zones.\n        """\n        nearby_demand = []\n        nearby_supply = []\n\n        for zone in self.demand_zones:\n            if zone.active and self._pc_diff_abs(current_price, zone.s1) <= self.line_pc_display:\n                nearby_demand.append(zone.to_dict())\n\n        for zone in self.supply_zones:\n            if zone.active and self._pc_diff_abs(current_price, zone.s1) <= self.line_pc_display:\n                nearby_supply.append(zone.to_dict())\n\n        return {\n            "demand": nearby_demand[:5],   # max 5 to show\n            "supply": nearby_supply[:5],\n        }\n\n    def get_all_active_zones(self) -> dict:\n        """Return all active zones for the dashboard zones table."""\n        return {\n            "demand": [z.to_dict() for z in self.demand_zones if z.active],\n            "supply": [z.to_dict() for z in self.supply_zones if z.active],\n            "demand_total": len(self.demand_zones),\n            "supply_total": len(self.supply_zones),\n            "demand_active": sum(1 for z in self.demand_zones if z.active),\n            "supply_active": sum(1 for z in self.supply_zones if z.active),\n        }\n\n    def get_stats(self, df: pd.DataFrame) -> dict:\n        """Return zone stats for the dashboard indicator panel."""\n        if df.empty:\n            return {}\n        price = df.iloc[-1]["close"]\n        nearby = self.get_nearby_zones(price)\n        return {\n            "active_demand_zones": sum(1 for z in self.demand_zones if z.active),\n            "active_supply_zones": sum(1 for z in self.supply_zones if z.active),\n            "nearby_demand": len(nearby["demand"]),\n            "nearby_supply": len(nearby["supply"]),\n            "nearest_demand": nearby["demand"][0]["s1"] if nearby["demand"] else None,\n            "nearest_supply": nearby["supply"][0]["s1"] if nearby["supply"] else None,\n        }\n', 'risk/manager.py': '"""\nrisk/manager.py\nRisk Management Layer\n\nControls:\n  - Position sizing (volatility-based + max % of portfolio)\n  - Stop-loss / take-profit enforcement\n  - Max open positions\n  - Daily loss kill switch (pauses all trading if -X% hit)\n  - Exposure limits\n"""\n\nimport os\nfrom datetime import datetime, date\nfrom dataclasses import dataclass, field\nfrom loguru import logger\n\n\n@dataclass\nclass RiskConfig:\n    max_position_pct: float = 0.10    # max 10% of portfolio per position\n    max_open_positions: int = 5\n    stop_loss_pct: float = 0.02       # 2% stop-loss\n    take_profit_pct: float = 0.04     # 4% take-profit\n    max_daily_loss_pct: float = 0.03  # kill switch at -3%\n    min_confidence: float = 0.60      # only trade signals with confidence > 60%\n    min_cash_reserve_pct: float = 0.20  # always keep 20% in cash\n\n\n@dataclass\nclass PositionInfo:\n    symbol: str\n    qty: float\n    avg_cost: float\n    current_price: float\n    strategy: str\n    stop_loss: float\n    take_profit: float\n    opened_at: datetime = field(default_factory=datetime.utcnow)\n\n    @property\n    def unrealized_pnl(self) -> float:\n        return (self.current_price - self.avg_cost) * self.qty\n\n    @property\n    def unrealized_pnl_pct(self) -> float:\n        return (self.current_price - self.avg_cost) / self.avg_cost\n\n    @property\n    def should_stop_loss(self) -> bool:\n        return self.current_price <= self.stop_loss\n\n    @property\n    def should_take_profit(self) -> bool:\n        return self.current_price >= self.take_profit\n\n\nclass RiskManager:\n\n    def __init__(self, config: RiskConfig = None):\n        self.config = config or RiskConfig(\n            max_position_pct=float(os.getenv("MAX_POSITION_SIZE", 0.10)),\n            stop_loss_pct=float(os.getenv("STOP_LOSS_PCT", 0.02)),\n            take_profit_pct=float(os.getenv("TAKE_PROFIT_PCT", 0.04)),\n            max_daily_loss_pct=float(os.getenv("MAX_DAILY_LOSS", 0.03)),\n            max_open_positions=int(os.getenv("MAX_OPEN_POSITIONS", 5)),\n        )\n        self.positions: dict[str, PositionInfo] = {}\n        self.daily_start_value: float = None\n        self.daily_realized_pnl: float = 0.0\n        self.trading_halted: bool = False\n        self.halt_reason: str = ""\n        self.trade_count_today: int = 0\n        self._today: date = date.today()\n\n    # ── Daily reset ───────────────────────────────────────────────────────────\n\n    def set_starting_value(self, portfolio_value: float):\n        today = date.today()\n        if today != self._today:\n            self.daily_realized_pnl = 0.0\n            self.trade_count_today = 0\n            self.trading_halted = False\n            self.halt_reason = ""\n            self._today = today\n            logger.info(f"New trading day — daily P&L reset")\n        self.daily_start_value = portfolio_value\n\n    # ── Pre-trade checks ──────────────────────────────────────────────────────\n\n    def can_trade(self, symbol: str, action: str,\n                  signal_confidence: float, portfolio_value: float,\n                  available_cash: float) -> tuple[bool, str]:\n        """\n        Returns (allowed: bool, reason: str).\n        Call this BEFORE placing any order.\n        """\n        # Kill switch\n        if self.trading_halted:\n            return False, f"Trading halted: {self.halt_reason}"\n\n        # Signal confidence\n        if signal_confidence < self.config.min_confidence:\n            return False, f"Signal confidence {signal_confidence:.0%} below minimum {self.config.min_confidence:.0%}"\n\n        # Already in this position for BUY\n        if action == "BUY" and symbol in self.positions:\n            return False, f"Already holding {symbol}"\n\n        # Max positions\n        if action == "BUY" and len(self.positions) >= self.config.max_open_positions:\n            return False, f"Max open positions ({self.config.max_open_positions}) reached"\n\n        # Cash reserve\n        min_cash = portfolio_value * self.config.min_cash_reserve_pct\n        if action == "BUY" and available_cash < min_cash:\n            return False, f"Cash reserve too low (${available_cash:.0f} < ${min_cash:.0f} required)"\n\n        # Daily loss kill switch\n        if self.daily_start_value:\n            daily_pnl_pct = self.daily_realized_pnl / self.daily_start_value\n            if daily_pnl_pct <= -self.config.max_daily_loss_pct:\n                self.halt_trading(f"Daily loss limit hit: {daily_pnl_pct:.1%}")\n                return False, self.halt_reason\n\n        return True, "OK"\n\n    # ── Position sizing ───────────────────────────────────────────────────────\n\n    def calculate_position_size(self, symbol: str, price: float,\n                                portfolio_value: float, available_cash: float,\n                                signal_confidence: float = 1.0) -> int:\n        """\n        Returns number of shares to buy.\n        Uses volatility-adjusted position sizing.\n        """\n        # Max dollar amount for this position\n        max_dollars = portfolio_value * self.config.max_position_pct\n\n        # Scale by signal confidence\n        scaled_dollars = max_dollars * signal_confidence\n\n        # Don\'t use more than available cash\n        usable_cash = available_cash * (1 - self.config.min_cash_reserve_pct)\n        position_dollars = min(scaled_dollars, usable_cash)\n\n        if position_dollars < price:\n            return 0   # can\'t afford even 1 share\n\n        shares = int(position_dollars / price)\n        logger.info(f"Position size {symbol}: {shares} shares "\n                    f"(${position_dollars:.0f} of ${portfolio_value:.0f} portfolio)")\n        return shares\n\n    # ── Stop-loss / take-profit levels ────────────────────────────────────────\n\n    def calculate_levels(self, entry_price: float) -> tuple[float, float]:\n        """Returns (stop_loss_price, take_profit_price)."""\n        stop_loss   = entry_price * (1 - self.config.stop_loss_pct)\n        take_profit = entry_price * (1 + self.config.take_profit_pct)\n        return round(stop_loss, 2), round(take_profit, 2)\n\n    # ── Position tracking ─────────────────────────────────────────────────────\n\n    def open_position(self, symbol: str, qty: int, fill_price: float, strategy: str):\n        stop_loss, take_profit = self.calculate_levels(fill_price)\n        self.positions[symbol] = PositionInfo(\n            symbol=symbol, qty=qty, avg_cost=fill_price,\n            current_price=fill_price, strategy=strategy,\n            stop_loss=stop_loss, take_profit=take_profit\n        )\n        self.trade_count_today += 1\n        logger.info(f"Position opened: {qty} {symbol} @ ${fill_price:.2f} | "\n                    f"SL=${stop_loss:.2f} TP=${take_profit:.2f}")\n\n    def close_position(self, symbol: str, fill_price: float) -> float:\n        """Close position, record P&L, return realized P&L."""\n        if symbol not in self.positions:\n            return 0\n        pos = self.positions.pop(symbol)\n        pnl = (fill_price - pos.avg_cost) * pos.qty\n        self.daily_realized_pnl += pnl\n        self.trade_count_today += 1\n        logger.info(f"Position closed: {pos.qty} {symbol} @ ${fill_price:.2f} | "\n                    f"P&L=${pnl:+.2f}")\n        return pnl\n\n    def update_price(self, symbol: str, price: float):\n        if symbol in self.positions:\n            self.positions[symbol].current_price = price\n\n    # ── Stop-loss monitoring ──────────────────────────────────────────────────\n\n    def check_exits(self) -> list[dict]:\n        """\n        Call this every tick / every minute.\n        Returns list of positions that should be closed immediately.\n        """\n        exits = []\n        for symbol, pos in list(self.positions.items()):\n            if pos.should_stop_loss:\n                exits.append({\n                    "symbol": symbol,\n                    "reason": "stop_loss",\n                    "price": pos.current_price,\n                    "pnl_pct": pos.unrealized_pnl_pct\n                })\n                logger.warning(f"🛑 STOP LOSS triggered: {symbol} @ ${pos.current_price:.2f} "\n                               f"(entry ${pos.avg_cost:.2f}, loss {pos.unrealized_pnl_pct:.1%})")\n            elif pos.should_take_profit:\n                exits.append({\n                    "symbol": symbol,\n                    "reason": "take_profit",\n                    "price": pos.current_price,\n                    "pnl_pct": pos.unrealized_pnl_pct\n                })\n                logger.success(f"🎯 TAKE PROFIT hit: {symbol} @ ${pos.current_price:.2f} "\n                               f"(entry ${pos.avg_cost:.2f}, gain {pos.unrealized_pnl_pct:.1%})")\n        return exits\n\n    # ── Kill switch ───────────────────────────────────────────────────────────\n\n    def halt_trading(self, reason: str):\n        self.trading_halted = True\n        self.halt_reason = reason\n        logger.critical(f"🚨 TRADING HALTED: {reason}")\n\n    def resume_trading(self):\n        self.trading_halted = False\n        self.halt_reason = ""\n        logger.info("Trading resumed")\n\n    # ── Summary ───────────────────────────────────────────────────────────────\n\n    def get_summary(self) -> dict:\n        total_unrealized = sum(p.unrealized_pnl for p in self.positions.values())\n        return {\n            "open_positions": len(self.positions),\n            "daily_realized_pnl": round(self.daily_realized_pnl, 2),\n            "total_unrealized_pnl": round(total_unrealized, 2),\n            "total_pnl": round(self.daily_realized_pnl + total_unrealized, 2),\n            "trading_halted": self.trading_halted,\n            "halt_reason": self.halt_reason,\n            "trade_count_today": self.trade_count_today,\n            "positions": [\n                {\n                    "symbol": p.symbol,\n                    "qty": p.qty,\n                    "avg_cost": p.avg_cost,\n                    "current_price": p.current_price,\n                    "unrealized_pnl": round(p.unrealized_pnl, 2),\n                    "unrealized_pnl_pct": round(p.unrealized_pnl_pct * 100, 2),\n                    "stop_loss": p.stop_loss,\n                    "take_profit": p.take_profit,\n                    "strategy": p.strategy,\n                }\n                for p in self.positions.values()\n            ]\n        }\n', 'execution/broker.py': '"""\nexecution/broker.py\nAlpaca order execution engine.\n- Places market / limit / bracket orders\n- Polls for fills and updates positions\n- Supports paper and live trading via env var\n"""\n\nimport os\nimport time\nimport alpaca_trade_api as tradeapi\nfrom loguru import logger\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n\nclass AlpacaBroker:\n\n    def __init__(self):\n        self.api = tradeapi.REST(\n            key_id=os.getenv("ALPACA_API_KEY"),\n            secret_key=os.getenv("ALPACA_SECRET_KEY"),\n            base_url=os.getenv("ALPACA_BASE_URL", "https://paper-api.alpaca.markets"),\n        )\n        self.env = os.getenv("ENV", "paper")\n        logger.info(f"Broker initialized in {self.env.upper()} mode")\n        self._verify_connection()\n\n    def _verify_connection(self):\n        try:\n            account = self.api.get_account()\n            logger.success(f"Connected to Alpaca | "\n                           f"Equity: ${float(account.equity):,.2f} | "\n                           f"Cash: ${float(account.cash):,.2f} | "\n                           f"Buying Power: ${float(account.buying_power):,.2f}")\n        except Exception as e:\n            logger.error(f"Alpaca connection failed: {e}")\n            raise\n\n    # ── Account ───────────────────────────────────────────────────────────────\n\n    def get_account(self) -> dict:\n        try:\n            a = self.api.get_account()\n            return {\n                "equity": float(a.equity),\n                "cash": float(a.cash),\n                "buying_power": float(a.buying_power),\n                "portfolio_value": float(a.portfolio_value),\n                "day_trade_count": int(a.daytrade_count),\n                "pattern_day_trader": a.pattern_day_trader,\n                "trading_blocked": a.trading_blocked,\n                "account_blocked": a.account_blocked,\n            }\n        except Exception as e:\n            logger.error(f"get_account error: {e}")\n            return {}\n\n    def get_positions(self) -> list[dict]:\n        try:\n            positions = self.api.list_positions()\n            return [\n                {\n                    "symbol": p.symbol,\n                    "qty": float(p.qty),\n                    "avg_cost": float(p.avg_entry_price),\n                    "current_price": float(p.current_price),\n                    "market_value": float(p.market_value),\n                    "unrealized_pnl": float(p.unrealized_pl),\n                    "unrealized_pnl_pct": float(p.unrealized_plpc) * 100,\n                }\n                for p in positions\n            ]\n        except Exception as e:\n            logger.error(f"get_positions error: {e}")\n            return []\n\n    def is_market_open(self) -> bool:\n        try:\n            clock = self.api.get_clock()\n            return clock.is_open\n        except Exception as e:\n            logger.error(f"is_market_open error: {e}")\n            return False\n\n    # ── Orders ────────────────────────────────────────────────────────────────\n\n    def buy_market(self, symbol: str, qty: int, strategy: str = "") -> dict | None:\n        """Place a market buy order."""\n        if qty <= 0:\n            logger.warning(f"Invalid qty {qty} for {symbol}")\n            return None\n        try:\n            logger.info(f"Placing BUY {qty} {symbol} (market) [{strategy}]")\n            order = self.api.submit_order(\n                symbol=symbol,\n                qty=qty,\n                side="buy",\n                type="market",\n                time_in_force="day",\n            )\n            logger.success(f"Order submitted: {order.id} | {qty} {symbol}")\n            return {\n                "order_id": order.id,\n                "symbol": symbol,\n                "side": "buy",\n                "qty": qty,\n                "status": order.status,\n            }\n        except Exception as e:\n            logger.error(f"buy_market error {symbol}: {e}")\n            return None\n\n    def sell_market(self, symbol: str, qty: int, strategy: str = "") -> dict | None:\n        """Place a market sell order."""\n        if qty <= 0:\n            return None\n        try:\n            logger.info(f"Placing SELL {qty} {symbol} (market) [{strategy}]")\n            order = self.api.submit_order(\n                symbol=symbol,\n                qty=qty,\n                side="sell",\n                type="market",\n                time_in_force="day",\n            )\n            logger.success(f"Sell order submitted: {order.id}")\n            return {\n                "order_id": order.id,\n                "symbol": symbol,\n                "side": "sell",\n                "qty": qty,\n                "status": order.status,\n            }\n        except Exception as e:\n            logger.error(f"sell_market error {symbol}: {e}")\n            return None\n\n    def buy_bracket(self, symbol: str, qty: int,\n                    stop_loss: float, take_profit: float,\n                    strategy: str = "") -> dict | None:\n        """\n        Bracket order — automatically sets stop-loss and take-profit\n        on the exchange. Best practice for risk management.\n        """\n        if qty <= 0:\n            return None\n        try:\n            logger.info(f"Placing BRACKET BUY {qty} {symbol} "\n                        f"SL=${stop_loss:.2f} TP=${take_profit:.2f}")\n            order = self.api.submit_order(\n                symbol=symbol,\n                qty=qty,\n                side="buy",\n                type="market",\n                time_in_force="day",\n                order_class="bracket",\n                stop_loss={"stop_price": str(round(stop_loss, 2))},\n                take_profit={"limit_price": str(round(take_profit, 2))},\n            )\n            return {\n                "order_id": order.id,\n                "symbol": symbol,\n                "side": "buy",\n                "qty": qty,\n                "stop_loss": stop_loss,\n                "take_profit": take_profit,\n                "status": order.status,\n            }\n        except Exception as e:\n            logger.error(f"buy_bracket error {symbol}: {e}")\n            return None\n\n    def sell_all(self, symbol: str) -> dict | None:\n        """Close entire position in a symbol."""\n        try:\n            positions = {p["symbol"]: p for p in self.get_positions()}\n            if symbol not in positions:\n                logger.warning(f"No position to close for {symbol}")\n                return None\n            qty = positions[symbol]["qty"]\n            return self.sell_market(symbol, int(qty))\n        except Exception as e:\n            logger.error(f"sell_all error {symbol}: {e}")\n            return None\n\n    def cancel_all_orders(self):\n        """Emergency cancel all open orders."""\n        try:\n            self.api.cancel_all_orders()\n            logger.warning("All open orders cancelled")\n        except Exception as e:\n            logger.error(f"cancel_all_orders error: {e}")\n\n    def liquidate_all(self):\n        """Emergency liquidate all positions."""\n        logger.critical("EMERGENCY LIQUIDATION — closing all positions")\n        try:\n            self.api.close_all_positions()\n            logger.critical("All positions closed")\n        except Exception as e:\n            logger.error(f"liquidate_all error: {e}")\n\n    def wait_for_fill(self, order_id: str, timeout: int = 30) -> float | None:\n        """Poll for fill price. Returns filled price or None."""\n        for _ in range(timeout):\n            try:\n                order = self.api.get_order(order_id)\n                if order.status == "filled":\n                    return float(order.filled_avg_price)\n                if order.status in ("cancelled", "expired", "rejected"):\n                    logger.warning(f"Order {order_id} ended with status: {order.status}")\n                    return None\n                time.sleep(1)\n            except Exception as e:\n                logger.error(f"wait_for_fill error: {e}")\n                time.sleep(1)\n        logger.warning(f"Order {order_id} not filled within {timeout}s")\n        return None\n', 'dashboard/app.py': '"""\ndashboard/app.py\nFlask web dashboard with real-time updates.\nShows: portfolio value, open positions, P&L, signals, live prices, trade log.\n"""\n\nimport os\nimport json\nfrom datetime import datetime, timedelta\nfrom flask import Flask, render_template, jsonify, request\nfrom flask_socketio import SocketIO, emit\nfrom loguru import logger\n\n# These are injected by main.py at startup\n_risk_manager = None\n_broker = None\n_price_cache = None\n_strategies = {}\n\napp = Flask(__name__)\napp.secret_key = os.getenv("FLASK_SECRET_KEY", "dev-secret-change-me")\nsocketio = SocketIO(app, cors_allowed_origins="*")\n\n\ndef init_dashboard(risk_manager, broker, price_cache, strategies):\n    global _risk_manager, _broker, _price_cache, _strategies\n    _risk_manager = risk_manager\n    _broker = broker\n    _price_cache = price_cache\n    _strategies = strategies\n\n\ndef emit_update():\n    """Push live data to all connected dashboard clients."""\n    try:\n        account = _broker.get_account() if _broker else {}\n        risk = _risk_manager.get_summary() if _risk_manager else {}\n\n        prices = {}\n        if _price_cache:\n            for sym in (os.getenv("TRADING_SYMBOLS", "SPY,QQQ").split(",")):\n                p = _price_cache.get_price(sym.strip())\n                if p:\n                    prices[sym.strip()] = round(p, 2)\n\n        socketio.emit("update", {\n            "account": account,\n            "risk": risk,\n            "prices": prices,\n            "timestamp": datetime.utcnow().isoformat(),\n        })\n    except Exception as e:\n        logger.error(f"emit_update error: {e}")\n\n\n# ── Routes ────────────────────────────────────────────────────────────────────\n\n@app.route("/")\ndef index():\n    return render_template("dashboard.html",\n                           symbols=os.getenv("TRADING_SYMBOLS", "SPY,QQQ").split(","))\n\n\n@app.route("/api/account")\ndef api_account():\n    if not _broker:\n        return jsonify({"error": "Broker not connected"})\n    return jsonify(_broker.get_account())\n\n\n@app.route("/api/positions")\ndef api_positions():\n    if not _broker:\n        return jsonify([])\n    return jsonify(_broker.get_positions())\n\n\n@app.route("/api/risk")\ndef api_risk():\n    if not _risk_manager:\n        return jsonify({})\n    return jsonify(_risk_manager.get_summary())\n\n\n@app.route("/api/prices")\ndef api_prices():\n    if not _price_cache:\n        return jsonify({})\n    symbols = os.getenv("TRADING_SYMBOLS", "SPY,QQQ").split(",")\n    prices = {}\n    for sym in symbols:\n        p = _price_cache.get_price(sym.strip())\n        if p:\n            prices[sym.strip()] = round(p, 2)\n    return jsonify(prices)\n\n\n@app.route("/api/zones")\ndef api_zones():\n    """Return all active S&D zones for the dashboard zones table."""\n    sd = _strategies.get("supply_demand")\n    if not sd:\n        return jsonify({"demand": [], "supply": []})\n    price = None\n    if _price_cache:\n        symbols = os.getenv("TRADING_SYMBOLS", "SPY").split(",")\n        price = _price_cache.get_price(symbols[0].strip())\n    zones = sd.get_all_active_zones()\n    if price:\n        zones["nearby"] = sd.get_nearby_zones(price)\n    return jsonify(zones)\n\n\n@app.route("/api/bars/<symbol>")\ndef api_bars(symbol):\n    if not _price_cache:\n        return jsonify([])\n    n = int(request.args.get("n", 60))\n    df = _price_cache.get_bars_df(symbol.upper(), n=n)\n    if df.empty:\n        return jsonify([])\n    df = df.reset_index()\n    df["timestamp"] = df["timestamp"].astype(str)\n    return jsonify(df.to_dict("records"))\n\n\n@app.route("/api/halt", methods=["POST"])\ndef api_halt():\n    """Manual kill switch from dashboard."""\n    if _risk_manager:\n        _risk_manager.halt_trading("Manual halt via dashboard")\n    if _broker:\n        _broker.cancel_all_orders()\n    return jsonify({"status": "halted"})\n\n\n@app.route("/api/resume", methods=["POST"])\ndef api_resume():\n    if _risk_manager:\n        _risk_manager.resume_trading()\n    return jsonify({"status": "resumed"})\n\n\n@app.route("/api/liquidate", methods=["POST"])\ndef api_liquidate():\n    """Emergency liquidate all — use with caution."""\n    if _broker:\n        _broker.liquidate_all()\n    if _risk_manager:\n        _risk_manager.halt_trading("Post-liquidation halt")\n    return jsonify({"status": "liquidated"})\n\n\n@socketio.on("connect")\ndef on_connect():\n    logger.info("Dashboard client connected")\n    emit_update()\n\n\ndef run_dashboard(host="0.0.0.0", port=5000, debug=False):\n    socketio.run(app, host=host, port=port, debug=debug, use_reloader=False)\n', 'dashboard/templates/dashboard.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Algo Trader Dashboard</title>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/socket.io/4.7.2/socket.io.js"></script>\n<script src="https://cdn.plot.ly/plotly-2.27.0.min.js"></script>\n<style>\n  *{box-sizing:border-box;margin:0;padding:0}\n  body{font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',sans-serif;background:#0f1117;color:#f0f1f5;font-size:14px}\n  header{background:#1a1d23;border-bottom:1px solid #2d3139;padding:0 1.5rem;display:flex;align-items:center;justify-content:space-between;height:56px}\n  .brand{font-size:16px;font-weight:600;display:flex;align-items:center;gap:8px}\n  .live-dot{width:8px;height:8px;border-radius:50%;background:#1f9d6f;animation:pulse 2s infinite}\n  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}\n  .status-bar{font-size:12px;color:#828695}\n  main{max-width:1200px;margin:0 auto;padding:1.5rem}\n  .metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:1.5rem}\n  .metric{background:#1e2029;border:1px solid #333644;border-radius:10px;padding:1rem}\n  .metric-label{font-size:11px;color:#828695;text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px}\n  .metric-val{font-size:22px;font-weight:600}\n  .metric-val.up{color:#3dd38e}\n  .metric-val.down{color:#ff6b63}\n  .metric-val.neutral{color:#f0f1f5}\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1rem}\n  .card{background:#1e2029;border:1px solid #333644;border-radius:10px;padding:1.25rem}\n  .card-title{font-size:12px;font-weight:600;color:#828695;text-transform:uppercase;letter-spacing:.05em;margin-bottom:1rem}\n  table{width:100%;border-collapse:collapse;font-size:13px}\n  th{font-size:11px;color:#828695;text-transform:uppercase;letter-spacing:.04em;padding:6px 0;border-bottom:1px solid #333644;text-align:left;font-weight:500}\n  td{padding:10px 0;border-bottom:1px solid #262834;vertical-align:middle}\n  tr:last-child td{border-bottom:none}\n  .badge{display:inline-block;padding:3px 8px;border-radius:99px;font-size:11px;font-weight:600}\n  .badge-buy{background:#0a2e20;color:#3dd38e}\n  .badge-sell{background:#3a1d1c;color:#ff6b63}\n  .badge-hold{background:#262834;color:#828695}\n  .up{color:#3dd38e}\n  .down{color:#ff6b63}\n  .controls{display:flex;gap:8px;margin-bottom:1.5rem;flex-wrap:wrap}\n  .btn{padding:8px 18px;border-radius:8px;border:1px solid #454857;background:#262834;color:#f0f1f5;font-size:13px;font-weight:500;cursor:pointer}\n  .btn:hover{background:#333644}\n  .btn-danger{border-color:#ff6b63;color:#ff6b63}\n  .btn-danger:hover{background:#3a1d1c}\n  .btn-warning{border-color:#f0c349;color:#f0c349}\n  .btn-warning:hover{background:#3a2f12}\n  .btn-success{border-color:#3dd38e;color:#3dd38e}\n  .btn-success:hover{background:#0a2e20}\n  .halted-banner{background:#3a1d1c;border:1px solid #ff6b63;border-radius:8px;padding:12px 16px;color:#ff6b63;font-weight:500;margin-bottom:1rem;display:none}\n  .price-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:8px}\n  .price-tile{background:#262834;border-radius:8px;padding:10px 14px}\n  .price-symbol{font-size:12px;color:#828695;font-weight:600}\n  .price-val{font-size:18px;font-weight:600;margin-top:2px}\n  #chartDiv{height:260px}\n  .full-width{grid-column:1/-1}\n</style>\n</head>\n<body>\n\n<header>\n  <div class="brand">\n    <div class="live-dot"></div>\n    🤖 Algo Trader\n  </div>\n  <div class="status-bar" id="statusBar">Connecting...</div>\n</header>\n\n<main>\n  <div class="halted-banner" id="haltedBanner">\n    ⚠️ Trading Halted — <span id="haltReason"></span>\n  </div>\n\n  <div class="controls">\n    <button class="btn btn-danger" onclick="haltTrading()">🛑 Halt Trading</button>\n    <button class="btn btn-success" onclick="resumeTrading()">▶ Resume Trading</button>\n    <button class="btn btn-warning" onclick="liquidateAll()">⚡ Emergency Liquidate All</button>\n  </div>\n\n  <div class="metrics" id="metrics">\n    <div class="metric"><div class="metric-label">Portfolio Value</div><div class="metric-val neutral" id="m-equity">—</div></div>\n    <div class="metric"><div class="metric-label">Cash Available</div><div class="metric-val neutral" id="m-cash">—</div></div>\n    <div class="metric"><div class="metric-label">Today\'s P&L</div><div class="metric-val neutral" id="m-pnl">—</div></div>\n    <div class="metric"><div class="metric-label">Open Positions</div><div class="metric-val neutral" id="m-positions">—</div></div>\n    <div class="metric"><div class="metric-label">Trades Today</div><div class="metric-val neutral" id="m-trades">—</div></div>\n    <div class="metric"><div class="metric-label">Unrealized P&L</div><div class="metric-val neutral" id="m-unrealized">—</div></div>\n  </div>\n\n  <div class="card" style="margin-bottom:1rem">\n    <div class="card-title">Live Prices</div>\n    <div class="price-grid" id="priceGrid"></div>\n  </div>\n\n  <div class="grid2">\n    <div class="card">\n      <div class="card-title">Open Positions</div>\n      <table>\n        <thead>\n          <tr><th>Symbol</th><th>Qty</th><th>Avg Cost</th><th>Price</th><th>P&L</th><th>SL / TP</th></tr>\n        </thead>\n        <tbody id="positionsBody">\n          <tr><td colspan="6" style="color:#828695;text-align:center;padding:1.5rem">No open positions</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <div class="card">\n      <div class="card-title">Risk Monitor</div>\n      <table>\n        <thead><tr><th>Metric</th><th>Value</th></tr></thead>\n        <tbody id="riskBody"></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class="card full-width" style="margin-top:1rem">\n    <div class="card-title" style="display:flex;justify-content:space-between">\n      <span>Supply & Demand Zones</span>\n      <button class="btn" style="padding:4px 10px;font-size:11px" onclick="loadZones()">Refresh</button>\n    </div>\n    <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem">\n      <div>\n        <p style="font-size:11px;color:#3dd38e;font-weight:600;margin-bottom:8px">🟢 DEMAND ZONES (Buy)</p>\n        <table><thead><tr><th>Level (S1)</th><th>Zone</th><th>Status</th></tr></thead>\n        <tbody id="demandZones"><tr><td colspan="3" style="color:#828695;text-align:center">Loading...</td></tr></tbody></table>\n      </div>\n      <div>\n        <p style="font-size:11px;color:#ff6b63;font-weight:600;margin-bottom:8px">🔴 SUPPLY ZONES (Sell)</p>\n        <table><thead><tr><th>Level (S1)</th><th>Zone</th><th>Status</th></tr></thead>\n        <tbody id="supplyZones"><tr><td colspan="3" style="color:#828695;text-align:center">Loading...</td></tr></tbody></table>\n      </div>\n    </div>\n  </div>\n\n</main>\n\n<script>\nconst socket = io();\nconst $ = id => document.getElementById(id);\nconst fmt = (n, d=2) => n != null ? \'$\' + parseFloat(n).toLocaleString(\'en-US\', {minimumFractionDigits:d,maximumFractionDigits:d}) : \'—\';\nconst fmtPct = n => n != null ? (n >= 0 ? \'+\' : \'\') + parseFloat(n).toFixed(2) + \'%\' : \'—\';\nconst cls = n => n >= 0 ? \'up\' : \'down\';\n\nsocket.on(\'connect\', () => $(\'statusBar\').textContent = \'Connected — live\');\nsocket.on(\'disconnect\', () => $(\'statusBar\').textContent = \'Disconnected — reconnecting...\');\n\nsocket.on(\'update\', data => {\n  $(\'statusBar\').textContent = \'Updated \' + new Date().toLocaleTimeString();\n\n  const a = data.account || {};\n  $(\'m-equity\').textContent = fmt(a.equity);\n  $(\'m-cash\').textContent = fmt(a.cash);\n\n  const r = data.risk || {};\n  const pnl = r.total_pnl || 0;\n  $(\'m-pnl\').textContent = fmt(pnl);\n  $(\'m-pnl\').className = \'metric-val \' + (pnl >= 0 ? \'up\' : \'down\');\n  $(\'m-positions\').textContent = r.open_positions ?? \'—\';\n  $(\'m-trades\').textContent = r.trade_count_today ?? \'—\';\n\n  const unrealized = r.total_unrealized_pnl || 0;\n  $(\'m-unrealized\').textContent = fmt(unrealized);\n  $(\'m-unrealized\').className = \'metric-val \' + (unrealized >= 0 ? \'up\' : \'down\');\n\n  // Halt banner\n  if (r.trading_halted) {\n    $(\'haltedBanner\').style.display = \'block\';\n    $(\'haltReason\').textContent = r.halt_reason || \'\';\n  } else {\n    $(\'haltedBanner\').style.display = \'none\';\n  }\n\n  // Live prices\n  const prices = data.prices || {};\n  $(\'priceGrid\').innerHTML = Object.entries(prices).map(([sym, price]) => `\n    <div class="price-tile">\n      <div class="price-symbol">${sym}</div>\n      <div class="price-val">${fmt(price)}</div>\n    </div>`).join(\'\');\n\n  // Positions table\n  const positions = r.positions || [];\n  $(\'positionsBody\').innerHTML = positions.length\n    ? positions.map(p => `\n      <tr>\n        <td><strong>${p.symbol}</strong><br><span style="font-size:11px;color:#828695">${p.strategy}</span></td>\n        <td>${p.qty}</td>\n        <td>${fmt(p.avg_cost)}</td>\n        <td>${fmt(p.current_price)}</td>\n        <td class="${cls(p.unrealized_pnl)}">${fmt(p.unrealized_pnl)}<br><span style="font-size:11px">${fmtPct(p.unrealized_pnl_pct)}</span></td>\n        <td style="font-size:12px"><span class="down">SL ${fmt(p.stop_loss)}</span><br><span class="up">TP ${fmt(p.take_profit)}</span></td>\n      </tr>`).join(\'\')\n    : \'<tr><td colspan="6" style="color:#828695;text-align:center;padding:1.5rem">No open positions</td></tr>\';\n\n  // Risk table\n  $(\'riskBody\').innerHTML = [\n    [\'Daily P&L\', `<span class="${cls(r.daily_realized_pnl)}">${fmt(r.daily_realized_pnl)}</span>`],\n    [\'Open Positions\', r.open_positions + \' / 5\'],\n    [\'Trading Status\', r.trading_halted ? \'<span class="down">HALTED</span>\' : \'<span class="up">ACTIVE</span>\'],\n    [\'Trades Today\', r.trade_count_today ?? 0],\n  ].map(([k, v]) => `<tr><td style="color:#828695">${k}</td><td>${v}</td></tr>`).join(\'\');\n});\n\nfunction loadZones(){\n  fetch(\'/api/zones\').then(r=>r.json()).then(data=>{\n    const fmtZ = zones => zones.length\n      ? zones.map(z=>`<tr>\n          <td><strong>$${z.s1}</strong></td>\n          <td style="font-size:12px">$${z.bot} – $${z.top}<br><span style="color:#828695">${z.height_pct?.toFixed(2)}%</span></td>\n          <td>${z.active ? \'<span class="up">Active</span>\' : \'<span style="color:#828695">Hit</span>\'}</td>\n        </tr>`).join(\'\')\n      : \'<tr><td colspan="3" style="color:#828695;text-align:center;padding:1rem">None detected</td></tr>\';\n    $(\'demandZones\').innerHTML = fmtZ(data.demand || []);\n    $(\'supplyZones\').innerHTML = fmtZ(data.supply || []);\n  }).catch(()=>{});\n}\nloadZones();\nsetInterval(loadZones, 60000);\n\nfunction haltTrading(){\n  if(confirm(\'Halt all trading?\')) fetch(\'/api/halt\',{method:\'POST\'}).then(()=>alert(\'Trading halted\'));\n}\nfunction resumeTrading(){\n  fetch(\'/api/resume\',{method:\'POST\'}).then(()=>alert(\'Trading resumed\'));\n}\nfunction liquidateAll(){\n  if(confirm(\'⚠️ EMERGENCY LIQUIDATE ALL POSITIONS? This cannot be undone.\'))\n    fetch(\'/api/liquidate\',{method:\'POST\'}).then(()=>alert(\'All positions liquidated\'));\n}\n</script>\n</body>\n</html>\n', 'main.py': '"""\nmain.py\nAlgo Trader — Main Orchestrator\n\nWires together:\n  - Alpaca live data feed (WebSocket)\n  - Momentum + Mean Reversion strategies\n  - Risk manager (position sizing, stop-loss, kill switch)\n  - Alpaca broker (order execution)\n  - Flask dashboard (real-time web UI)\n\nRun: python main.py\n"""\n\nimport os\nimport time\nimport signal\nimport threading\nimport schedule\nfrom datetime import datetime\nfrom loguru import logger\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nfrom data.database import init_db, save_signal, save_trade, save_sd_zone, deactivate_sd_zone\nfrom data.feed import start_feed, price_cache\nfrom strategies.momentum import MomentumStrategy\nfrom strategies.mean_reversion import MeanReversionStrategy\nfrom strategies.supply_demand import SupplyDemandStrategy\nfrom risk.manager import RiskManager, RiskConfig\nfrom execution.broker import AlpacaBroker\nfrom dashboard.app import init_dashboard, run_dashboard, emit_update, socketio\n\n# ── Config ────────────────────────────────────────────────────────────────────\n\nSYMBOLS = [s.strip() for s in os.getenv("TRADING_SYMBOLS", "SPY,QQQ,AAPL").split(",")]\nMIN_BARS_BEFORE_TRADING = 35    # wait for enough history before signaling\nSTRATEGY_INTERVAL_SECONDS = 60  # run strategies every 60 seconds\nLOG_FILE = "logs/algo_trader_{time}.log"\n\n# ── Logging ───────────────────────────────────────────────────────────────────\n\nlogger.add(LOG_FILE, rotation="1 day", retention="30 days",\n           level=os.getenv("LOG_LEVEL", "INFO"), format="{time} | {level} | {message}")\n\n# ── Global state ──────────────────────────────────────────────────────────────\n\nbroker: AlpacaBroker = None\nrisk_manager: RiskManager = None\nstrategies = {}\n_running = True\n\n\n# ── Strategy runner ───────────────────────────────────────────────────────────\n\ndef run_strategies():\n    """Called on a schedule — checks signals for every symbol."""\n    if not broker or not risk_manager:\n        return\n\n    if not broker.is_market_open():\n        logger.debug("Market closed — skipping strategy run")\n        return\n\n    if risk_manager.trading_halted:\n        logger.warning(f"Trading halted ({risk_manager.halt_reason}) — skipping")\n        return\n\n    # Refresh account state\n    account = broker.get_account()\n    if not account:\n        return\n\n    portfolio_value = account.get("portfolio_value", 0)\n    cash = account.get("cash", 0)\n    risk_manager.set_starting_value(portfolio_value)\n\n    for symbol in SYMBOLS:\n        df = price_cache.get_bars_df(symbol, n=100)\n        if df.empty or len(df) < MIN_BARS_BEFORE_TRADING:\n            logger.debug(f"{symbol}: not enough bars yet ({len(df)}/{MIN_BARS_BEFORE_TRADING})")\n            continue\n\n        # Update risk manager with latest price\n        price = price_cache.get_price(symbol)\n        if price:\n            risk_manager.update_price(symbol, price)\n\n        # Run both strategies, use whichever fires first\n        for strategy_name, strategy in strategies.items():\n            signal = strategy.generate_signal(symbol, df)\n\n            if signal is None:\n                continue\n\n            action = signal["action"]\n            sig_price = signal["price"]\n            confidence = signal["confidence"]\n            reason = signal["reason"]\n\n            logger.info(f"Signal: {action} {symbol} via {strategy_name} "\n                        f"@ ${sig_price:.2f} (confidence={confidence:.0%})")\n\n            # Save signal to DB\n            save_signal(symbol, strategy_name, action, sig_price, reason, confidence)\n\n            # Persist S&D zone to DB if this is a supply/demand signal\n            if strategy_name == "supply_demand" and signal:\n                zone_top = signal.get("zone_top", sig_price)\n                zone_bot = signal.get("zone_bot", sig_price)\n                zone_type = "D" if action == "BUY" else "S"\n                save_sd_zone(symbol, zone_type, sig_price, zone_top, zone_bot)\n                if signal.get("confidence", 0) >= 0.75:   # only deactivate on HIT not NEAR\n                    deactivate_sd_zone(symbol, zone_type, sig_price)\n\n            # ── BUY ──────────────────────────────────────────────────────────\n            if action == "BUY":\n                allowed, reason_blocked = risk_manager.can_trade(\n                    symbol, "BUY", confidence, portfolio_value, cash\n                )\n                if not allowed:\n                    logger.info(f"Trade blocked for {symbol}: {reason_blocked}")\n                    continue\n\n                qty = risk_manager.calculate_position_size(\n                    symbol, sig_price, portfolio_value, cash, confidence\n                )\n                if qty == 0:\n                    logger.warning(f"Position size 0 for {symbol} — skipping")\n                    continue\n\n                stop_loss, take_profit = risk_manager.calculate_levels(sig_price)\n                order = broker.buy_bracket(symbol, qty, stop_loss, take_profit, strategy_name)\n\n                if order:\n                    fill_price = broker.wait_for_fill(order["order_id"])\n                    if fill_price:\n                        risk_manager.open_position(symbol, qty, fill_price, strategy_name)\n                        save_trade(order["order_id"], symbol, "buy", qty,\n                                   limit_price=fill_price, strategy=strategy_name)\n                        cash -= qty * fill_price\n                break  # don\'t run second strategy if first already fired\n\n            # ── SELL ─────────────────────────────────────────────────────────\n            elif action == "SELL":\n                if symbol not in risk_manager.positions:\n                    continue\n\n                allowed, reason_blocked = risk_manager.can_trade(\n                    symbol, "SELL", confidence, portfolio_value, cash\n                )\n                if not allowed:\n                    logger.info(f"Sell blocked for {symbol}: {reason_blocked}")\n                    continue\n\n                order = broker.sell_all(symbol)\n                if order:\n                    fill_price = broker.wait_for_fill(order["order_id"])\n                    if fill_price:\n                        pnl = risk_manager.close_position(symbol, fill_price)\n                        save_trade(order["order_id"], symbol, "sell",\n                                   order["qty"], limit_price=fill_price,\n                                   strategy=strategy_name)\n                break\n\n    # Push update to dashboard\n    emit_update()\n\n\ndef check_stop_losses():\n    """Check stop-loss / take-profit on every tick cycle."""\n    if not broker or not risk_manager:\n        return\n    exits = risk_manager.check_exits()\n    for exit_signal in exits:\n        symbol = exit_signal["symbol"]\n        logger.warning(f"Auto-exit {symbol}: {exit_signal[\'reason\']}")\n        order = broker.sell_all(symbol)\n        if order:\n            fill = broker.wait_for_fill(order["order_id"], timeout=15)\n            if fill:\n                risk_manager.close_position(symbol, fill)\n                save_trade(order["order_id"], symbol, "sell",\n                           order["qty"], limit_price=fill,\n                           strategy=exit_signal["reason"])\n\n\ndef on_tick(symbol: str, price: float, volume: float):\n    """Called on every price tick — updates risk manager and checks exits."""\n    risk_manager.update_price(symbol, price)\n    check_stop_losses()\n\n\ndef end_of_day_cleanup():\n    """Close all positions 5 minutes before market close."""\n    logger.info("End-of-day cleanup — closing all positions")\n    if broker:\n        broker.cancel_all_orders()\n        broker.liquidate_all()\n    if risk_manager:\n        for symbol in list(risk_manager.positions.keys()):\n            risk_manager.positions.pop(symbol, None)\n    logger.info("End-of-day cleanup complete")\n\n\n# ── Graceful shutdown ─────────────────────────────────────────────────────────\n\ndef shutdown(signum, frame):\n    global _running\n    logger.warning("Shutdown signal received — closing positions and stopping")\n    _running = False\n    if broker:\n        broker.cancel_all_orders()\n        broker.liquidate_all()\n    exit(0)\n\n\nsignal.signal(signal.SIGINT, shutdown)\nsignal.signal(signal.SIGTERM, shutdown)\n\n\n# ── Bootstrap ─────────────────────────────────────────────────────────────────\n\ndef main():\n    global broker, risk_manager, strategies\n\n    logger.info("=" * 60)\n    logger.info("🤖 Algo Trader starting up")\n    logger.info(f"   Symbols: {SYMBOLS}")\n    logger.info(f"   Mode: {os.getenv(\'ENV\', \'paper\').upper()}")\n    logger.info("=" * 60)\n\n    # 1. Database\n    logger.info("Initializing database...")\n    init_db()\n\n    # 2. Broker connection\n    logger.info("Connecting to Alpaca...")\n    broker = AlpacaBroker()\n    account = broker.get_account()\n    logger.info(f"Account value: ${account.get(\'equity\', 0):,.2f}")\n\n    # 3. Risk manager\n    logger.info("Initializing risk manager...")\n    risk_manager = RiskManager()\n    risk_manager.set_starting_value(account.get("portfolio_value", 0))\n\n    # 4. Strategies\n    logger.info("Loading strategies...")\n    strategies = {\n        "momentum": MomentumStrategy(fast_ma=10, slow_ma=30),\n        "mean_reversion": MeanReversionStrategy(bb_period=20),\n        "supply_demand": SupplyDemandStrategy(\n            min_pc_change=0.25,\n            max_pc_zone=0.6,\n            alerts_pc_near=1.5,\n            max_zones=100,\n        ),\n    }\n    logger.info(f"Strategies loaded: {list(strategies.keys())}")\n\n    # 5. Live data feed\n    logger.info(f"Starting live data feed for {SYMBOLS}...")\n    feed = start_feed(SYMBOLS, tick_callbacks=[on_tick])\n    logger.info("Feed started — waiting 30s for data to accumulate...")\n    time.sleep(30)\n\n    # 6. Dashboard\n    logger.info(f"Starting dashboard on port {os.getenv(\'DASHBOARD_PORT\', 5000)}...")\n    init_dashboard(risk_manager, broker, price_cache, strategies)\n    dashboard_thread = threading.Thread(\n        target=run_dashboard,\n        kwargs={"host": "0.0.0.0", "port": int(os.getenv("DASHBOARD_PORT", 5000))},\n        daemon=True,\n        name="Dashboard"\n    )\n    dashboard_thread.start()\n\n    # 7. Schedule\n    schedule.every(STRATEGY_INTERVAL_SECONDS).seconds.do(run_strategies)\n    schedule.every().day.at("15:55").do(end_of_day_cleanup)  # 5 min before close\n\n    logger.success("🚀 Algo Trader is LIVE — dashboard at http://localhost:5000")\n    logger.info(f"Running strategies every {STRATEGY_INTERVAL_SECONDS}s")\n\n    # Main loop\n    while _running:\n        try:\n            schedule.run_pending()\n            time.sleep(1)\n        except Exception as e:\n            logger.error(f"Main loop error: {e}")\n            time.sleep(5)\n\n\nif __name__ == "__main__":\n    main()\n', 'backtest.py': '"""\nbacktest.py\nBacktester — run strategies against historical data before live trading.\n\nUsage:\n  python backtest.py --symbol SPY --start 2022-01-01 --end 2024-01-01\n  python backtest.py --symbol AAPL --strategy momentum\n"""\n\nimport argparse\nfrom datetime import datetime\nimport pandas as pd\nimport numpy as np\nimport yfinance as yf\nfrom loguru import logger\n\nfrom strategies.momentum import MomentumStrategy\nfrom strategies.mean_reversion import MeanReversionStrategy\n\n\n# ── Engine ────────────────────────────────────────────────────────────────────\n\nclass Backtester:\n\n    def __init__(self, strategy, initial_capital: float = 10_000,\n                 stop_loss_pct: float = 0.02, take_profit_pct: float = 0.04,\n                 commission: float = 0.001):\n        self.strategy = strategy\n        self.capital = initial_capital\n        self.initial_capital = initial_capital\n        self.stop_loss_pct = stop_loss_pct\n        self.take_profit_pct = take_profit_pct\n        self.commission = commission  # 0.1% per trade\n\n        self.position = 0\n        self.avg_cost = 0\n        self.stop_loss_price = 0\n        self.take_profit_price = 0\n\n        self.trades = []\n        self.equity_curve = []\n\n    def run(self, df: pd.DataFrame, symbol: str) -> dict:\n        logger.info(f"Running backtest: {symbol} | {len(df)} bars | "\n                    f"${self.initial_capital:,.0f} starting capital")\n\n        for i in range(50, len(df)):\n            window = df.iloc[:i]\n            row = df.iloc[i]\n            price = row["Close"]\n            ts = row.name\n\n            # Check stop-loss / take-profit if in position\n            if self.position > 0:\n                if price <= self.stop_loss_price:\n                    self._sell(price, ts, "stop_loss")\n                    continue\n                if price >= self.take_profit_price:\n                    self._sell(price, ts, "take_profit")\n                    continue\n\n            # Rename columns for strategy compatibility\n            window_renamed = window.rename(columns={\n                "Open":"open","High":"high","Low":"low",\n                "Close":"close","Volume":"volume"\n            })\n            signal = self.strategy.generate_signal(symbol, window_renamed)\n\n            if signal:\n                if signal["action"] == "BUY" and self.position == 0:\n                    self._buy(price, ts, signal["confidence"])\n                elif signal["action"] == "SELL" and self.position > 0:\n                    self._sell(price, ts, "signal")\n\n            # Record equity\n            equity = self.capital + (self.position * price if self.position > 0 else 0)\n            self.equity_curve.append({"date": ts, "equity": equity})\n\n        # Close any open position at end\n        if self.position > 0:\n            final_price = df.iloc[-1]["Close"]\n            self._sell(final_price, df.iloc[-1].name, "end_of_test")\n\n        return self._calc_stats(df)\n\n    def _buy(self, price: float, ts, confidence: float):\n        max_invest = self.capital * min(0.95, confidence)\n        shares = int(max_invest / price)\n        if shares == 0:\n            return\n        cost = shares * price * (1 + self.commission)\n        self.capital -= cost\n        self.position = shares\n        self.avg_cost = price\n        self.stop_loss_price = price * (1 - self.stop_loss_pct)\n        self.take_profit_price = price * (1 + self.take_profit_pct)\n        self.trades.append({\n            "date": ts, "side": "BUY", "price": price,\n            "shares": shares, "cost": cost, "pnl": 0\n        })\n\n    def _sell(self, price: float, ts, reason: str):\n        proceeds = self.position * price * (1 - self.commission)\n        cost_basis = self.position * self.avg_cost\n        pnl = proceeds - cost_basis\n        self.capital += proceeds\n        self.trades[-1 if self.trades else 0]  # update last trade\n        self.trades.append({\n            "date": ts, "side": "SELL", "price": price,\n            "shares": self.position, "proceeds": proceeds,\n            "pnl": pnl, "reason": reason\n        })\n        self.position = 0\n        self.avg_cost = 0\n\n    def _calc_stats(self, df: pd.DataFrame) -> dict:\n        if not self.trades:\n            return {"error": "No trades executed"}\n\n        sell_trades = [t for t in self.trades if t["side"] == "SELL"]\n        if not sell_trades:\n            return {"error": "No completed trades"}\n\n        pnls = [t["pnl"] for t in sell_trades]\n        total_return = (self.capital - self.initial_capital) / self.initial_capital\n\n        wins = [p for p in pnls if p > 0]\n        losses = [p for p in pnls if p <= 0]\n\n        equity = pd.DataFrame(self.equity_curve).set_index("date")["equity"]\n        rolling_max = equity.cummax()\n        drawdown = (equity - rolling_max) / rolling_max\n        max_drawdown = drawdown.min()\n\n        daily_returns = equity.pct_change().dropna()\n        sharpe = (daily_returns.mean() / daily_returns.std()) * (252 ** 0.5) if daily_returns.std() > 0 else 0\n\n        stats = {\n            "strategy": self.strategy.NAME,\n            "initial_capital": self.initial_capital,\n            "final_capital": round(self.capital, 2),\n            "total_return_pct": round(total_return * 100, 2),\n            "total_trades": len(sell_trades),\n            "winning_trades": len(wins),\n            "losing_trades": len(losses),\n            "win_rate": round(len(wins) / max(len(sell_trades), 1) * 100, 1),\n            "avg_win": round(np.mean(wins), 2) if wins else 0,\n            "avg_loss": round(np.mean(losses), 2) if losses else 0,\n            "profit_factor": round(sum(wins) / max(abs(sum(losses)), 1), 2),\n            "max_drawdown_pct": round(max_drawdown * 100, 2),\n            "sharpe_ratio": round(sharpe, 2),\n            "best_trade": round(max(pnls), 2),\n            "worst_trade": round(min(pnls), 2),\n        }\n        return stats\n\n\n# ── CLI ───────────────────────────────────────────────────────────────────────\n\ndef print_results(stats: dict):\n    print("\\n" + "=" * 50)\n    print(f"  BACKTEST RESULTS — {stats.get(\'strategy\', \'?\')}")\n    print("=" * 50)\n    for k, v in stats.items():\n        if k == "strategy": continue\n        label = k.replace("_", " ").title()\n        if "pct" in k or "rate" in k:\n            print(f"  {label:<25} {v}%")\n        elif "capital" in k or "trade" in k.lower() and "trades" not in k:\n            print(f"  {label:<25} ${v:,.2f}")\n        else:\n            print(f"  {label:<25} {v}")\n    print("=" * 50)\n\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser(description="Algo Trader Backtester")\n    parser.add_argument("--symbol", default="SPY", help="Stock symbol (default: SPY)")\n    parser.add_argument("--start",  default="2021-01-01", help="Start date YYYY-MM-DD")\n    parser.add_argument("--end",    default="2024-01-01", help="End date YYYY-MM-DD")\n    parser.add_argument("--capital",default=10000, type=float, help="Starting capital")\n    parser.add_argument("--strategy", default="both",\n                        choices=["momentum", "mean_reversion", "both"])\n    args = parser.parse_args()\n\n    logger.info(f"Downloading {args.symbol} data {args.start} → {args.end}...")\n    df = yf.download(args.symbol, start=args.start, end=args.end, auto_adjust=True)\n\n    if df.empty:\n        logger.error("No data downloaded — check symbol and dates")\n        exit(1)\n\n    logger.info(f"Downloaded {len(df)} bars")\n\n    strats = []\n    if args.strategy in ("momentum", "both"):\n        strats.append(MomentumStrategy())\n    if args.strategy in ("mean_reversion", "both"):\n        strats.append(MeanReversionStrategy())\n\n    for strat in strats:\n        bt = Backtester(strat, initial_capital=args.capital)\n        stats = bt.run(df.copy(), args.symbol)\n        print_results(stats)\n\n    # Buy-and-hold comparison\n    bh_return = (df["Close"].iloc[-1] - df["Close"].iloc[0]) / df["Close"].iloc[0] * 100\n    print(f"\\n  📊 Buy & Hold {args.symbol}: {bh_return:.1f}% over same period")\n'}

